import hmac
import json

def parse_signed_volunteer_update(payload: str, signature: str, key: str) -> list[str]:
    if not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    expected = hmac.new(key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature[7:], expected):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload)
    except json.JSONDecodeError as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(document, dict) or not isinstance(document.get('volunteers'), list):
        raise ValueError('invalid volunteers')
    names = []
    for volunteer in document['volunteers']:
        if not isinstance(volunteer, dict) or not isinstance(volunteer.get('name'), str) or (not isinstance(volunteer.get('active'), bool)):
            raise ValueError('invalid volunteer')
        if volunteer['active']:
            names.append(volunteer['name'])
    return sorted(names, key=str.casefold)

