def parse_aid_awards(xml_text: str) -> list[tuple[str, str, int]]:
    root = ET.fromstring(xml_text)
    awards = []
    for award in root.findall('award'):
        student = (award.findtext('student') or '').strip()
        term = (award.findtext('term') or '').strip()
        amount = int((award.findtext('amount') or '').strip())
        if amount < 0:
            raise ValueError('amount must not be negative')
        awards.append((student, term, amount))
    return sorted(awards, key=lambda item: (item[0], item[1]))

