import xml.sax
import xml.sax.handler

class _AwardHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.awards = []
        self.current = None
        self.field = None
        self.text = []

    def startElement(self, name, attrs):
        if name == 'award':
            self.current = {}
        elif self.current is not None and name in ('student', 'term', 'amount'):
            self.field = name
            self.text = []

    def characters(self, content):
        if self.field is not None:
            self.text.append(content)

    def endElement(self, name):
        if self.current is not None and name in ('student', 'term', 'amount'):
            self.current[name] = ''.join(self.text).strip()
            self.field = None
            self.text = []
        elif name == 'award' and self.current is not None:
            student = self.current.get('student', '')
            term = self.current.get('term', '')
            amount = int(self.current.get('amount', ''))
            if amount < 0:
                raise ValueError('amount must not be negative')
            self.awards.append((student, term, amount))
            self.current = None

def parse_aid_awards(xml_text: str) -> list[tuple[str, str, int]]:
    handler = _AwardHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    parser.parse(io.StringIO(xml_text))
    return sorted(handler.awards, key=lambda item: (item[0], item[1]))

