import os
_ITERATIONS = 100000

def make_quote_access_record(code: str) -> str:
    if not isinstance(code, str) or not code:
        raise ValueError('code must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode('utf-8'), salt, _ITERATIONS)
    return salt.hex() + ':' + digest.hex()

def check_quote_access_code(code: str, record: str) -> bool:
    if not isinstance(code, str) or not code or (not isinstance(record, str)):
        return False
    parts = record.split(':')
    if len(parts) != 2:
        return False
    try:
        salt = bytes.fromhex(parts[0])
        expected = bytes.fromhex(parts[1])
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', code.encode('utf-8'), salt, _ITERATIONS)
    return hmac.compare_digest(actual, expected)

