import os

def load_certificate(base_dir: str, filename: str) -> dict[str, object]:
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, filename))
    if os.path.commonpath((base, path)) != base:
        raise ValueError('path is outside base directory')
    values = {}
    with open(path, 'r', encoding='utf-8') as handle:
        for line in handle:
            line = line.strip()
            if not line:
                continue
            if line.count('=') != 1:
                raise ValueError('malformed certificate line')
            key, value = (part.strip() for part in line.split('=', 1))
            values[key] = value
    required = {'address', 'energy_class', 'annual_kwh'}
    if not required.issubset(values):
        raise ValueError('missing certificate field')
    try:
        annual_kwh = int(values['annual_kwh'])
    except ValueError as exc:
        raise ValueError('annual_kwh must be an integer') from exc
    return {'address': values['address'], 'energy_class': values['energy_class'].upper(), 'annual_kwh': annual_kwh}

