import ast
import operator

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise NameError(node.id)
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _value(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left = _value(node.left, names)
        right = _value(node.right, names)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _value(node.values[0], names)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result):
                return result
            if isinstance(node.op, ast.Or) and result:
                return result
            result = _value(child, names)
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        checks = []
        for op, child in zip(node.ops, node.comparators):
            right = _value(child, names)
            checks.append({ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}[type(op)](left, right))
            left = right
        return all(checks)
    raise ValueError('unsupported expression')

def filter_inspections(inspections: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    tree = ast.parse(rule, mode='eval')
    return [inspection for inspection in inspections if _value(tree.body, inspection)]

import csv
import os
import tempfile

def export_yield_predictions(predictions: list[tuple[str, float]], destination: str) -> int:
    for crop, value in predictions:
        if value < 0:
            raise ValueError('yield values must not be negative')
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary_path = tempfile.mkstemp(prefix='.yield-', suffix='.csv', dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='') as output:
            writer = csv.writer(output, lineterminator='\n')
            writer.writerow(['crop', 'predicted_yield'])
            for crop, value in sorted(predictions, key=lambda item: item[0]):
                writer.writerow([crop, f'{value:.2f}'])
        os.replace(temporary_path, destination)
    except Exception:
        try:
            os.unlink(temporary_path)
        except FileNotFoundError:
            pass
        raise
    return len(predictions)

