import json

def parse_badge_event(event_json: str, token: str, expected_token: str) -> dict:
    try:
        data = json.loads(event_json)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid event') from exc
    if not isinstance(data, dict):
        raise ValueError('invalid event')
    if not hmac.compare_digest(token, expected_token):
        raise ValueError('invalid token')
    badge_id = data.get('badge_id')
    action = data.get('action')
    timestamp = data.get('timestamp')
    if not isinstance(badge_id, str) or not badge_id:
        raise ValueError('invalid badge id')
    if action not in ('enter', 'exit'):
        raise ValueError('invalid action')
    if not isinstance(timestamp, int) or isinstance(timestamp, bool) or timestamp < 0:
        raise ValueError('invalid timestamp')
    return {'badge_id': badge_id, 'action': action, 'timestamp': timestamp}

