def export_license_manifest(assets: list[dict], destination: str) -> int:
    for asset in assets:
        if asset['fee'] < 0:
            raise ValueError('fee must be non-negative')
    selected = sorted((asset for asset in assets if asset['licensed'] is True), key=lambda asset: asset['asset_id'])
    parent = os.path.dirname(destination) or '.'
    descriptor, temporary = tempfile.mkstemp(prefix='.manifest-', suffix='.tmp', dir=parent)
    os.close(descriptor)
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['asset_id', 'title', 'licensee', 'fee'])
            for asset in selected:
                writer.writerow([asset['asset_id'], asset['title'], asset['licensee'], asset['fee']])
        os.replace(temporary, destination)
    except Exception:
        if os.path.exists(temporary):
            os.unlink(temporary)
        raise
    return len(selected)

