def process_fares(trips: list[dict[str, object]], rule: str) -> dict[str, object]:
    try:
        tree = ast.parse(rule, mode='eval')
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc
    allowed = {'min': min, 'max': max, 'round': round}

    def evaluate(node, names):
        if isinstance(node, ast.Expression):
            return evaluate(node.body, names)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in names:
            return names[node.id]
        if isinstance(node, ast.Name) and node.id in allowed:
            return allowed[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (evaluate(node.left, names), evaluate(node.right, names))
            return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = evaluate(node.operand, names)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            values = [evaluate(x, names) for x in node.values]
            return all(values) if isinstance(node.op, ast.And) else any(values)
        if isinstance(node, ast.Compare):
            values = [evaluate(node.left, names)] + [evaluate(x, names) for x in node.comparators]
            ops = {ast.Lt: lambda a, b: a < b, ast.LtE: lambda a, b: a <= b, ast.Eq: lambda a, b: a == b, ast.NotEq: lambda a, b: a != b, ast.GtE: lambda a, b: a >= b, ast.Gt: lambda a, b: a > b}
            return all((ops[type(op)](a, b) for op, a, b in zip(node.ops, values, values[1:])))
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in allowed) and (not node.keywords):
            return allowed[node.func.id](*[evaluate(x, names) for x in node.args])
        raise ValueError('invalid rule')
    ids = []
    total = 0.0
    for trip in trips:
        fare = trip['base_fare'] * (1.2 if trip['peak'] else 1.0)
        try:
            selected = evaluate(tree, {'fare': fare, 'zones': trip['zones'], 'peak': trip['peak']})
        except (KeyError, NameError, TypeError, ValueError, ZeroDivisionError) as exc:
            raise ValueError('invalid rule') from exc
        if selected:
            ids.append(trip['id'])
            total += fare
    return {'ids': ids, 'total': round(total, 2)}

