import hmac
import json

def verify_and_list_lots(payload: str, signature: str, signing_key: str) -> list[dict]:
    expected = hmac.new(signing_key.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    lots = document.get('lots') if isinstance(document, dict) else None
    if not isinstance(lots, list):
        raise ValueError('invalid payload')
    for lot in lots:
        if not isinstance(lot, dict):
            raise ValueError('invalid payload')
        if not all((isinstance(lot.get(field), str) for field in ('id', 'title', 'status'))):
            raise ValueError('invalid payload')
        if not isinstance(lot.get('current_bid'), (int, float)) or isinstance(lot.get('current_bid'), bool):
            raise ValueError('invalid payload')
    return sorted((lot for lot in lots if lot['status'] == 'open'), key=lambda lot: (-lot['current_bid'], lot['id']))

