import operator

def select_offset_projects(projects: list[dict], rule: str) -> list[str]:
    tree = ast.parse(rule, mode='eval').body

    def visit(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp):
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            if type(node.op) not in ops:
                raise ValueError('unsupported operator')
            return ops[type(node.op)](visit(node.left, values), visit(node.right, values))
        if isinstance(node, ast.UnaryOp):
            value = visit(node.operand, values)
            if isinstance(node.op, ast.USub):
                return -value
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.Not):
                return not value
            raise ValueError('unsupported operator')
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                result = True
                for item in node.values:
                    result = visit(item, values)
                    if not result:
                        return result
                return result
            result = False
            for item in node.values:
                result = visit(item, values)
                if result:
                    return result
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left, values)
            comparisons = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Gt: operator.gt, ast.GtE: operator.ge}
            for op, comparator in zip(node.ops, node.comparators):
                right = visit(comparator, values)
                if type(op) not in comparisons or not comparisons[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}):
            args = [visit(arg, values) for arg in node.args]
            if node.keywords:
                raise ValueError('keywords unsupported')
            return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
        raise ValueError('unsupported expression')
    selected = [p for p in projects if visit(tree, p)]
    return [p['id'] for p in sorted(selected, key=lambda p: (-p['credits'], p['id']))]

