import os

def enforce_log_retention(base_dir: str, log_names: list[str], keep: int) -> list[str]:
    if keep < 0:
        raise ValueError('keep must not be negative')
    base = os.path.realpath(base_dir)
    paths = []
    for name in log_names:
        path = os.path.realpath(os.path.join(base, name))
        try:
            if os.path.commonpath([base, path]) != base:
                raise ValueError('log path is outside base directory')
        except ValueError:
            raise ValueError('log path is outside base directory')
        paths.append((name, path))
    existing = [(name, path, os.path.getmtime(path)) for name, path in paths if os.path.isfile(path)]
    existing.sort(key=lambda item: (item[2], item[0]))
    removed = existing[:-keep] if keep else existing
    for name, path, _ in removed:
        os.remove(path)
    return [name for name, _, _ in removed]

