def list_dependencies(source_path: str) -> list[str]:
    if not os.path.isfile(source_path):
        raise FileNotFoundError(source_path)
    result = subprocess.run(['grep', '-E', '^(import|from) ', source_path], capture_output=True, text=True, check=False)
    if result.returncode not in (0, 1):
        raise OSError(result.stderr.strip() or 'grep failed')
    dependencies = set()
    for line in result.stdout.splitlines():
        if line.startswith('import '):
            for item in line[7:].split(','):
                name = item.strip().split(' as ', 1)[0].strip()
                if name:
                    dependencies.add(name.split('.', 1)[0])
        elif line.startswith('from '):
            fields = line.split()
            if len(fields) >= 4 and fields[1] and (fields[2] == 'import'):
                dependencies.add(fields[1].split('.', 1)[0])
    return sorted(dependencies)

