import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Expression):
        return _evaluate(node.body, values)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise NameError(node.id)
        return values[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.Not, ast.UAdd, ast.USub)):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.Not):
            return not value
        return value if isinstance(node.op, ast.UAdd) else -value
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        functions = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        return functions[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _evaluate(node.values[0], values)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result):
                return result
            if isinstance(node.op, ast.Or) and result:
                return result
            result = _evaluate(item, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        functions = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
        for op, comparator in zip(node.ops, node.comparators):
            if type(op) not in functions:
                raise ValueError('unsupported rule')
            right = _evaluate(comparator, values)
            if not functions[type(op)](left, right):
                return False
            left = right
        return True
    raise ValueError('unsupported rule')

def total_billed(records: list[dict[str, float]], rule: str) -> float:
    try:
        tree = ast.parse(rule, mode='eval')
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc
    total = 0.0
    for record in records:
        values = {'amount': record['amount'], 'tax_rate': record['tax_rate'], 'discount': record['discount']}
        if _evaluate(tree, values):
            total += record['amount'] * (1 + record['tax_rate']) - record['discount']
    return float(total)

