import ast
import operator

def authorize_flights(flights: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    tree = ast.parse(rule, mode='eval').body
    names = {'altitude', 'distance', 'battery', 'wind'}

    def evaluate(node: ast.AST, values: dict[str, object]) -> object:
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in names:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            left = evaluate(node.left, values)
            right = evaluate(node.right, values)
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.UAdd, ast.USub, ast.Not}:
            value = evaluate(node.operand, values)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp):
            result = evaluate(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = evaluate(child, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            operations = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            for op, child in zip(node.ops, node.comparators):
                right = evaluate(child, values)
                if not operations[type(op)](left, right):
                    return False
                left = right
            return True
        raise ValueError('unsupported expression')
    selected = [flight for flight in flights if evaluate(tree, {key: flight[key] for key in names})]
    return sorted(selected, key=lambda flight: (flight['distance'], flight['id']))

