import xml.etree.ElementTree as ET

def parse_irrigation_plan(xml_text: str) -> list[tuple[str, int]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'plan':
        raise ValueError('root must be plan')
    zones = []
    for element in root.findall('zone'):
        try:
            zone_id = element.attrib['id']
            minutes = int(element.attrib['minutes'])
        except (KeyError, ValueError) as exc:
            raise ValueError('invalid zone') from exc
        if not zone_id or minutes < 0:
            raise ValueError('invalid zone')
        zones.append((zone_id, minutes))
    return sorted(zones)

