import xml.sax.handler

class _PlanHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.depth = 0
        self.root = None
        self.zones = []

    def startElement(self, name, attrs):
        self.depth += 1
        if self.depth == 1:
            self.root = name
        elif self.depth == 2 and name == 'zone':
            try:
                zone_id = attrs['id']
                minutes = int(attrs['minutes'])
            except (KeyError, ValueError) as exc:
                raise ValueError('invalid zone') from exc
            if not zone_id or minutes < 0:
                raise ValueError('invalid zone')
            self.zones.append((zone_id, minutes))

    def endElement(self, name):
        self.depth -= 1

def parse_irrigation_plan(xml_text: str) -> list[tuple[str, int]]:
    handler = _PlanHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.feed(xml_text)
        parser.close()
    except (xml.sax.SAXException, ValueError) as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid XML') from exc
    if handler.root != 'plan':
        raise ValueError('root must be plan')
    return sorted(handler.zones)

