import ast
import operator

def filter_sensors(sensors: list[dict[str, object]], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc

    def evaluate(node, sensor):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in {'pm25', 'temp', 'humidity'}:
                raise KeyError(node.id)
            return sensor[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            left = evaluate(node.left, sensor)
            right = evaluate(node.right, sensor)
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.UAdd, ast.USub, ast.Not}:
            value = evaluate(node.operand, sensor)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
            value = evaluate(node.values[0], sensor)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = evaluate(child, sensor)
            return value
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, sensor)
            for op, child in zip(node.ops, node.comparators):
                if type(op) not in {ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE}:
                    raise ValueError('invalid rule')
                right = evaluate(child, sensor)
                comparison = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)]
                if not comparison(left, right):
                    return False
                left = right
            return True
        raise ValueError('invalid rule')
    selected = [sensor for sensor in sensors if evaluate(tree, sensor)]
    selected.sort(key=lambda sensor: (-sensor['pm25'], sensor['id']))
    return [sensor['id'] for sensor in selected]

