import hmac
import json

def verify_quote_webhook(secret: str, body: str, signature: str) -> dict:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    expected = hmac.new(secret.encode('utf-8'), body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body)
    except (TypeError, ValueError):
        raise ValueError('invalid quotation')
    if not isinstance(data, dict) or data.get('event') != 'quotation':
        raise ValueError('invalid quotation')
    customer = data.get('customer')
    items = data.get('items')
    if not isinstance(customer, str) or not customer or (not isinstance(items, list)):
        raise ValueError('invalid quotation')
    total = 0
    count = 0
    for item in items:
        if not isinstance(item, dict):
            raise ValueError('invalid quotation')
        name = item.get('name')
        quantity = item.get('quantity')
        price = item.get('unit_price_cents')
        if not isinstance(name, str) or not name or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity <= 0) or (not isinstance(price, int)) or isinstance(price, bool) or (price < 0):
            raise ValueError('invalid quotation')
        count += quantity
        total += quantity * price
    return {'customer': customer, 'total_cents': total, 'item_count': count}

