import ast
import operator

def _evaluate(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError('unknown name')
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, names)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        left = _evaluate(node.left, names)
        right = _evaluate(node.right, names)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        value = _evaluate(node.values[0], names)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not value:
                    return value
            elif value:
                return value
            value = _evaluate(child, names)
        return value
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, names)
        ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
        for op, child in zip(node.ops, node.comparators):
            if type(op) not in ops:
                raise ValueError('invalid operator')
            right = _evaluate(child, names)
            if not ops[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords) and (1 <= len(node.args) <= 2):
        args = [_evaluate(arg, names) for arg in node.args]
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
    raise ValueError('invalid rule')

def select_results(results: list[dict], rule: str) -> list[dict]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except (SyntaxError, ValueError):
        raise ValueError('invalid rule')
    selected = []
