        raise ValueError('invalid root')
    matters = []
    for matter in root.findall('matter'):
        ident = matter.get('id')
        title_node = matter.find('title')
        deadline_node = matter.find('deadline')
        if not ident or title_node is None or deadline_node is None:
            raise ValueError('incomplete matter')
        title = (title_node.text or '').strip()
        deadline = (deadline_node.text or '').strip()
        if not title or not deadline:
            raise ValueError('incomplete matter')
        matters.append({'id': ident.strip(), 'title': title, 'deadline': deadline})
    return sorted(matters, key=lambda item: item['deadline'])

