import xml.sax.handler

class _DocketHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.matters = []
        self.current = None
        self.field = None
        self.text = []
        self.root_seen = False

    def startElement(self, name, attrs):
        if not self.root_seen:
            if name != 'docket':
                raise ValueError('invalid root')
            self.root_seen = True
        elif name == 'matter':
            self.current = {'id': attrs.get('id', '')}
        elif self.current is not None and name in ('title', 'deadline'):
            self.field = name
            self.text = []

    def characters(self, content):
        if self.field is not None:
            self.text.append(content)

    def endElement(self, name):
        if self.current is not None and name in ('title', 'deadline'):
            self.current[name] = ''.join(self.text).strip()
            self.field = None
            self.text = []
        elif name == 'matter' and self.current is not None:
            if not self.current.get('id', '').strip() or not self.current.get('title') or (not self.current.get('deadline')):
                raise ValueError('incomplete matter')
            self.current['id'] = self.current['id'].strip()
            self.matters.append(self.current)
            self.current = None

def parse_docket(xml_text: str) -> list[dict[str, str]]:
    handler = _DocketHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except (xml.sax.SAXException, ValueError) as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid XML') from exc
    if not handler.root_seen or handler.current is not None:
        raise ValueError('invalid XML')
    return sorted(handler.matters, key=lambda item: item['deadline'])

