import ast
import operator

def select_rooms(rooms: list[dict[str, object]], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval').body

        def ev(n, env):
            if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, bool)):
                return n.value
            if isinstance(n, ast.Name):
                return env[n.id]
            if isinstance(n, ast.BinOp):
                ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
                return ops[type(n.op)](ev(n.left, env), ev(n.right, env))
            if isinstance(n, ast.UnaryOp):
                return {ast.USub: operator.neg, ast.UAdd: operator.pos, ast.Not: operator.not_}[type(n.op)](ev(n.operand, env))
            if isinstance(n, ast.BoolOp):
                value = ev(n.values[0], env)
                for item in n.values[1:]:
                    if isinstance(n.op, ast.And) and (not value):
                        return value
                    if isinstance(n.op, ast.Or) and value:
                        return value
                    value = ev(item, env)
                return value
            if isinstance(n, ast.Compare):
                left = ev(n.left, env)
                for op, right_node in zip(n.ops, n.comparators):
                    right = ev(right_node, env)
                    if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in {'min', 'max', 'round'}) and (not n.keywords):
                args = [ev(x, env) for x in n.args]
                return {'min': min, 'max': max, 'round': round}[n.func.id](*args)
            raise ValueError()
        result = []
        for room in rooms:
            env = {'price': room['price'], 'guests': room['guests'], 'rating': room['rating'], 'nights': 1}
            if ev(tree, env):
                result.append(room)
        return [r['id'] for r in sorted(result, key=lambda r: (r['price'], r['id']))]
    except Exception as exc:
        raise ValueError('invalid rule') from exc

