import hashlib
import hmac
import os

def create_reviewer_record(name: str, password: str, rating: int) -> dict:
    normalized = name.strip()
    if not normalized or rating < 1 or rating > 5:
        raise ValueError('invalid reviewer record')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    credential = salt.hex() + ':' + digest.hex()
    return {'name': normalized, 'rating': rating, 'credential': credential}

def verify_reviewer(record: dict, password: str) -> bool:
    credential = record.get('credential')
    if not isinstance(credential, str) or ':' not in credential:
        return False
    salt_text, digest_text = credential.split(':', 1)
    try:
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

