import hashlib
import hmac
import json

def get_replenishment_items(payload: str, signature: str, secret: bytes) -> list[dict]:
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid payload') from exc
    items = data.get('items') if isinstance(data, dict) else None
    if not isinstance(items, list):
        raise ValueError('invalid items')
    for item in items:
        if not isinstance(item, dict):
            raise ValueError('invalid item')
        if not isinstance(item.get('sku'), str):
            raise ValueError('invalid sku')
        if type(item.get('quantity')) is not int:
            raise ValueError('invalid quantity')
        if type(item.get('reorder_level')) is not int:
            raise ValueError('invalid reorder level')
    return sorted((item for item in items if item['quantity'] < item['reorder_level']), key=lambda item: item['sku'])

