from typing import Mapping

def issue_case_receipt(case_number: str, applicant_name: str, stage: str, config: Mapping[str, str]) -> str:
    if stage not in {'received', 'review', 'interview', 'decided'}:
        raise ValueError('invalid stage')
    try:
        signing_key = config['signing_key']
    except KeyError as exc:
        raise ValueError('missing signing_key') from exc
    payload = f'{case_number}|{applicant_name.strip()}|{stage}'
    digest = hmac.new(signing_key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return f'{payload}.{digest}'

