import io
import xml.sax
import xml.sax.handler

def parse_expense_report(xml_text: str) -> list[tuple[str, float]]:

    class ExpenseHandler(xml.sax.handler.ContentHandler):

        def __init__(self):
            super().__init__()
            self.expenses = []
            self.current = None
            self.field = None
            self.text = []

        def startElement(self, name, attrs):
            if name == 'expense':
                self.current = {}
            elif name in ('employee', 'amount'):
                self.field = name
                self.text = []

        def characters(self, content):
            if self.field is not None:
                self.text.append(content)

        def endElement(self, name):
            if name in ('employee', 'amount'):
                if self.current is not None:
                    self.current[name] = ''.join(self.text).strip()
                self.field = None
                self.text = []
            elif name == 'expense':
                if self.current is None or 'employee' not in self.current or 'amount' not in self.current:
                    raise ValueError('expense is missing required data')
                amount = float(self.current['amount'])
                if amount < 0:
                    raise ValueError('amount cannot be negative')
                self.expenses.append((self.current['employee'], amount))
                self.current = None
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    handler = ExpenseHandler()
    parser.setContentHandler(handler)
    parser.parse(io.StringIO(xml_text))
    handler.expenses.sort(key=lambda entry: entry[1], reverse=True)
    return handler.expenses

