    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name == 'complaint':
            if any((key not in attrs for key in ('id', 'category', 'status'))):
                raise ValueError('missing complaint attribute')
            self.current = {key: attrs[key] for key in ('id', 'category', 'status')}
            self.summary = []
        elif name == 'summary' and self.current is not None:
            self.in_summary = True

    def characters(self, content):
        if self.in_summary:
            self.summary.append(content)

    def endElement(self, name):
        if name == 'summary':
            self.in_summary = False
        elif name == 'complaint' and self.current is not None:
            self.current['summary'] = ''.join(self.summary).strip()
            self.result.append(self.current)
            self.current = None

def load_complaints(xml_text: str) -> list[dict]:
    handler = _ComplaintHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except (xml.sax.SAXException, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'complaints':
        raise ValueError('invalid root')
    return sorted(handler.result, key=lambda item: item['id'])

