import ast
import operator

def select_alerts(alerts: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc
    names = {'amount', 'country_risk', 'prior_alerts', 'customer_age'}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    compare = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def visit(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in names:
                raise ValueError('unknown name')
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](visit(node.left, values), visit(node.right, values))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp):
            result = visit(node.values[0], values)
            for part in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = visit(part, values)
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left, values)
            for op, right_node in zip(node.ops, node.comparators):
                if type(op) not in compare:
                    raise ValueError('invalid comparison')
                right = visit(right_node, values)
                if not compare[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max'}) and (not node.keywords) and (len(node.args) >= 2):
            args = [visit(arg, values) for arg in node.args]
            return min(args) if node.func.id == 'min' else max(args)
        raise ValueError('invalid rule')
    result = []
    for alert in alerts:
        try:
            values = {name: alert[name] for name in names}
            if visit(tree, values):
                result.append(alert)
        except (KeyError, TypeError, ZeroDivisionError) as exc:
            raise ValueError('invalid alert or rule') from exc
    return result

