def _value(node, env):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in env:
            raise ValueError('unknown variable')
        return env[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _value(node.operand, env)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        left, right = (_value(node.left, env), _value(node.right, env))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
        values = [_value(x, env) for x in node.values]
        result = values[0]
        for value in values[1:]:
            result = value if result and isinstance(node.op, ast.And) or (not result and isinstance(node.op, ast.Or)) else result
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, env)
        for op, item in zip(node.ops, node.comparators):
            right = _value(item, env)
            try:
                passed = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right)
            except KeyError as exc:
                raise ValueError('invalid rule') from exc
            if not passed:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_value(x, env) for x in node.args])
    raise ValueError('invalid rule')

