    except Exception as exc:
        raise ValueError('invalid rule') from exc
    result = []
    for record in records:
        sequence = record['sequence'].upper()
        length = len(sequence)
        gc = 100.0 * sum((ch in 'GC' for ch in sequence)) / length if length else 0.0
        at = 100.0 * sum((ch in 'AT' for ch in sequence)) / length if length else 0.0
        try:
            matched = _value(tree.body, {'length': length, 'gc': gc, 'at': at})
        except ValueError:
            raise
        except Exception as exc:
            raise ValueError('invalid rule') from exc
        if matched:
            result.append(record['id'])
    return result

