import xml.etree.ElementTree as ET

def summarize_deliveries(xml_text: str) -> list[tuple[str, int]]:
    try:
        root = ET.fromstring(xml_text)
        totals: dict[str, int] = {}
        for delivery in root.findall('delivery'):
            destination = delivery.attrib.get('destination')
            if destination is None:
                raise ValueError('missing destination')
            total = totals.get(destination, 0)
            for item in delivery.findall('item'):
                value = item.attrib.get('quantity')
                if value is None:
                    raise ValueError('missing quantity')
                quantity = int(value)
                if quantity < 0:
                    raise ValueError('invalid quantity')
                total += quantity
            totals[destination] = total
        return sorted(totals.items())
    except (ET.ParseError, TypeError, ValueError):
        raise ValueError('invalid XML')

