import operator

def select_artifacts(artifacts: list[dict], expression: str) -> list[str]:
    try:
        tree = ast.parse(expression, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise ValueError('unknown variable')
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            fn = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)]
            return fn(evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = evaluate(node.operand, values)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            result = evaluate(node.values[0], values)
            for part in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = evaluate(part, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            checks = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}
            for op, comparator in zip(node.ops, node.comparators):
                right = evaluate(comparator, values)
                if type(op) not in checks or not checks[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
            if len(node.args) < 2:
                raise ValueError('invalid expression')
            args = [evaluate(arg, values) for arg in node.args]
            return min(args) if node.func.id == 'min' else max(args)
        raise ValueError('invalid expression')
    selected = []
    for artifact in artifacts:
        values = {key: artifact[key] for key in ('size_mb', 'age_days', 'downloads')}
        if evaluate(tree, values):
            selected.append(artifact)
    return [item['name'] for item in sorted(selected, key=lambda item: (-item['size_mb'], item['name']))]

