import ast

def _evaluate(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise NameError(node.id)
        return names[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left = _evaluate(node.left, names)
        right = _evaluate(node.right, names)
        return {ast.Add: lambda: left + right, ast.Sub: lambda: left - right, ast.Mult: lambda: left * right, ast.Div: lambda: left / right}[type(node.op)]()
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _evaluate(node.operand, names)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BoolOp):
        values = [_evaluate(x, names) for x in node.values]
        return all(values) if isinstance(node.op, ast.And) else any(values)
    if isinstance(node, ast.Compare):
        values = [_evaluate(node.left, names)] + [_evaluate(x, names) for x in node.comparators]
        ops = {ast.Lt: lambda a, b: a < b, ast.LtE: lambda a, b: a <= b, ast.Gt: lambda a, b: a > b, ast.GtE: lambda a, b: a >= b, ast.Eq: lambda a, b: a == b, ast.NotEq: lambda a, b: a != b}
        return all((ops[type(op)](a, b) for op, a, b in zip(node.ops, values, values[1:])))
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_evaluate(x, names) for x in node.args])
    raise ValueError('unsupported expression')

def filter_prior_authorizations(claims: list[dict], rule: str) -> dict:
    tree = ast.parse(rule, mode='eval').body
    selected = []
    total = 0
    for claim in claims:
        names = {key: claim[key] for key in ('age', 'days_supply', 'cost', 'tier')}
        result = _evaluate(tree, names)
        if not isinstance(result, bool):
            raise ValueError('rule must return bool')
        if result:
            selected.append(claim['id'])
            total += claim['cost']
    return {'selected_ids': selected, 'total_cost': total, 'count': len(selected)}

