import hmac

def verify_tile_request(tile: str, signature: str, secret: bytes) -> bool:
    parts = tile.split('/')
    if len(parts) != 3:
        return False
    if any((not part.isdigit() for part in parts)):
        return False
    if any((len(part) > 1 and part[0] == '0' for part in parts)):
        return False
    z, x, y = (int(part) for part in parts)
    if z > 22 or x >= 2 ** z or y >= 2 ** z:
        return False
    if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        return False
    expected = hmac.new(secret, tile.encode('utf-8'), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

