    digest = hashlib.pbkdf2_hmac('sha256', secret.encode('utf-8'), salt, 120000)
    return (campaign, f'pbkdf2$120000${salt.hex()}${digest.hex()}')

def verify_campaign_secret(secret: str, stored_value: str) -> bool:
    try:
        scheme, count_text, salt_text, digest_text = stored_value.split('$')
        if scheme != 'pbkdf2':
            return False
        count = int(count_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode('utf-8'), salt, count)
    return hmac.compare_digest(actual, expected)

