import math
import subprocess

def certify_consumption(path: str, limit: float) -> str:
    if limit < 0 or not math.isfinite(limit):
        raise ValueError('invalid limit')
    result = subprocess.run(['sort', '-n', path], check=True, capture_output=True, text=True)
    readings = []
    for line in result.stdout.splitlines():
        if line.strip():
            value = float(line)
            if value < 0 or not math.isfinite(value):
                raise ValueError('invalid reading')
            readings.append(value)
    if not readings:
        raise ValueError('no readings')
    middle = len(readings) // 2
    if len(readings) % 2:
        median = readings[middle]
    else:
        median = (readings[middle - 1] + readings[middle]) / 2
    return 'PASS' if median <= limit else 'FAIL'

