import xml.sax
import xml.sax.handler

class _PointsHandler(xml.sax.handler.ContentHandler):

    def __init__(self, member_id: str) -> None:
        super().__init__()
        self.member_id = member_id
        self.current_member = None
        self.total = 0

    def startElement(self, name, attrs):
        if name == 'member':
            self.current_member = attrs.get('id')
        elif name == 'transaction' and self.current_member == self.member_id:
            if attrs.get('status') == 'approved':
                self.total += int(attrs.get('points', '0'))

    def endElement(self, name):
        if name == 'member':
            self.current_member = None

def calculate_points(xml_text: str, member_id: str) -> int:
    handler = _PointsHandler(member_id)
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    return handler.total

