import os

def issue_certificate(certificate_id: str, pin: str) -> dict:
    if not certificate_id.strip() or len(pin) != 4 or (not pin.isdecimal()):
        raise ValueError('invalid certificate data')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'certificate_id': certificate_id, 'status': 'active', 'pin_hash': salt.hex() + '$' + digest.hex()}

def verify_certificate(record: dict, pin: str) -> bool:
    if not isinstance(record, dict) or record.get('status') != 'active':
        return False
    try:
        salt_text, digest_text = record['pin_hash'].split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (KeyError, ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

