import math

def apply_calibration(requester: dict, instrument: dict, reference_value: float, observed_value: float) -> dict:
    if not math.isfinite(reference_value) or not math.isfinite(observed_value):
        raise ValueError('calibration values must be finite')
    if requester['tenant_id'] != instrument['tenant_id']:
        raise PermissionError('calibration is not permitted')
    if requester['id'] != instrument['owner_id'] and 'calibration_admin' not in requester.get('roles', []):
        raise PermissionError('calibration is not permitted')
    correction = round(reference_value - observed_value, 6)
    result = dict(instrument)
    result['calibration_offset'] = correction
    result['calibrated_value'] = round(instrument['nominal_value'] + correction, 6)
    return result

