class _PlaceHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.root = None
        self.current = None
        self.in_address = False
        self.address_text = []
        self.places = []

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name == 'place':
            self.current = {'id': attrs['id'], 'name': attrs['name'], 'district': attrs['district']}
        elif name == 'address' and self.current is not None:
            self.in_address = True
            self.address_text = []

    def characters(self, content):
        if self.in_address:
            self.address_text.append(content)

    def endElement(self, name):
        if name == 'address' and self.current is not None:
            self.current['address'] = ''.join(self.address_text).strip()
            self.in_address = False
        elif name == 'place' and self.current is not None:
            self.current.setdefault('address', '')
            self.places.append(self.current)
            self.current = None

