import hashlib
import hmac
import os

def create_waitlist_record(patient_id: str, urgency: int, access_code: str) -> dict[str, object]:
    if not patient_id or not 1 <= urgency <= 5:
        raise ValueError('invalid waitlist record')
    return {'patient_id': patient_id, 'urgency': urgency, 'access_code': _encode_access_code(access_code)}

def _encode_access_code(access_code: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', access_code.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_waitlist_access(record: dict[str, object], access_code: str) -> bool:
    try:
        encoded = record['access_code']
        salt_text, digest_text = str(encoded).split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (KeyError, TypeError, ValueError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', access_code.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def prioritize_waitlist(records: list[dict[str, object]]) -> list[dict[str, object]]:
    return sorted(records, key=lambda record: (-int(record['urgency']), str(record['patient_id'])))

