import ast

def _value(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError('unknown name')
        return names[node.id]
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left, right = (_value(node.left, names), _value(node.right, names))
        return left + right if isinstance(node.op, ast.Add) else left - right if isinstance(node.op, ast.Sub) else left * right if isinstance(node.op, ast.Mult) else left / right
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _value(node.operand, names)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _value(node.values[0], names)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _value(item, names)
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, names)
        for op, item in zip(node.ops, node.comparators):
            right = _value(item, names)
            if not isinstance(op, (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)):
                raise ValueError('unsupported comparison')
            current = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]
            if not current:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_value(arg, names) for arg in node.args]
        if node.func.id == 'min':
            return min(*args)
        if node.func.id == 'max':
            return max(*args)
        return round(*args)
    raise ValueError('unsupported expression')

def select_vendors(vendors: list[dict], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval')
        selected = []
        for vendor in vendors:
            if _value(tree.body, vendor):
                selected.append(vendor)
        selected.sort(key=lambda item: (-item['rating'], item['price'], item['name']))
        return [item['name'] for item in selected]
    except (SyntaxError, KeyError, TypeError, ValueError, ZeroDivisionError, NameError) as exc:
        raise ValueError('invalid rule') from exc

