import hashlib
import hmac
import json

def rank_signed_profiles(payload: str, signature: str, secret: str) -> list[dict]:
    if not isinstance(signature, str):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        profiles = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(profiles, list):
        raise ValueError('invalid payload')
    for profile in profiles:
        if not isinstance(profile, dict):
            raise ValueError('invalid profile')
        if not isinstance(profile.get('id'), str):
            raise ValueError('invalid profile')
        if type(profile.get('risk_score')) is not int or not 1 <= profile['risk_score'] <= 10:
            raise ValueError('invalid profile')
        if type(profile.get('investable')) is not bool:
            raise ValueError('invalid profile')
    return sorted((profile for profile in profiles if profile['investable']), key=lambda profile: (-profile['risk_score'], profile['id']))

