    if not label or len(label) > 40:
        raise ValueError('invalid label')
    for device in devices:
        if device['id'] == device_id:
            if device['tenant_id'] != user['tenant_id'] or (device['owner_id'] != user['id'] and 'registry_admin' not in user.get('roles', [])):
