import ast
import operator

def select_replenishment(items: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    try:
        tree = ast.parse(rule, mode='eval').body
        allowed = {'stock', 'reorder_point', 'daily_sales', 'name'}

        def visit(node, values):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
                return node.value
            if isinstance(node, ast.Name) and node.id in allowed:
                return values[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand, values)
                return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                a, b = (visit(node.left, values), visit(node.right, values))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
            if isinstance(node, ast.BoolOp):
                result = visit(node.values[0], values)
                for child in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not result):
                        return result
                    if isinstance(node.op, ast.Or) and result:
                        return result
                    result = visit(child, values)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left, values)
                for op, part in zip(node.ops, node.comparators):
                    right = visit(part, values)
                    if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max'}) and (not node.keywords) and (len(node.args) >= 2):
                values_ = [visit(arg, values) for arg in node.args]
                return min(values_) if node.func.id == 'min' else max(values_)
            raise ValueError('invalid rule')
        selected = []
        for item in items:
            values = {key: item[key] for key in allowed}
            if visit(tree, values):
                selected.append(item)
        return sorted(selected, key=lambda item: (-(item['reorder_point'] - item['stock']), item['name']))
    except (SyntaxError, KeyError, NameError, TypeError, ZeroDivisionError, ValueError):
        raise ValueError('invalid rule')

