def reschedule_booking(requester: dict, booking: dict, new_start: str) -> dict:
    try:
        datetime.fromisoformat(new_start)
    except ValueError:
        raise ValueError('invalid start time')
    if booking.get('status') != 'scheduled':
        raise ValueError('booking is not scheduled')
    if requester.get('id') != booking.get('guest_id') and 'dispatcher' not in requester.get('roles', []):
        raise PermissionError('not authorized')
    result = booking.copy()
    result['start'] = new_start
    result['status'] = 'rescheduled'
    result['updated_by'] = requester['id']
    return result

