import xml.etree.ElementTree as ET

def extract_vineyard_records(xml_text: str) -> list[dict[str, object]]:
    try:
        root = ET.fromstring(xml_text)
        records = []
        for element in root.findall('record'):
            values = {}
            for field in ('name', 'variety', 'harvest', 'cases'):
                child = element.find(field)
                if child is None or child.text is None:
                    raise ValueError('missing field')
                values[field] = child.text.strip()
            try:
                harvest = int(values['harvest'])
                cases = int(values['cases'])
            except (TypeError, ValueError) as exc:
                raise ValueError('invalid number') from exc
            if not 1900 <= harvest <= 2100 or cases < 0:
                raise ValueError('value out of range')
            records.append({'name': values['name'], 'variety': values['variety'], 'harvest': harvest, 'cases': cases})
        return sorted(records, key=lambda item: (item['harvest'], item['name']))
    except ET.ParseError as exc:
        raise ValueError('malformed XML') from exc

