import xml.sax.handler

class _RecordHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.records = []
        self.current = None
        self.field = None
        self.text = []

    def startElement(self, name, attrs):
        if name == 'record':
            self.current = {}
        elif self.current is not None and name in ('name', 'variety', 'harvest', 'cases'):
            self.field = name
            self.text = []

    def characters(self, content):
        if self.field is not None:
            self.text.append(content)

    def endElement(self, name):
        if self.current is not None and name == self.field:
            self.current[name] = ''.join(self.text).strip()
            self.field = None
        elif name == 'record' and self.current is not None:
            self.records.append(self.current)
            self.current = None

def extract_vineyard_records(xml_text: str) -> list[dict[str, object]]:
    handler = _RecordHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        xml.sax.parseString(xml_text, handler)
    except (xml.sax.SAXException, ValueError) as exc:
        raise ValueError('malformed XML') from exc
    records = []
    for values in handler.records:
        try:
            if any((field not in values for field in ('name', 'variety', 'harvest', 'cases'))):
                raise ValueError('missing field')
            harvest = int(values['harvest'])
            cases = int(values['cases'])
        except (KeyError, TypeError, ValueError) as exc:
