import hashlib
import hmac
import json

def verify_certificate_webhook(payload: str, signature: str, signing_key: bytes) -> dict:
    if not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    expected = hmac.new(signing_key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict):
        raise ValueError('invalid payload')
    fields = ('certificate_id', 'region', 'megawatt_hours', 'issued_at')
    if any((field not in data for field in fields)):
        raise ValueError('invalid payload')
    if not isinstance(data['certificate_id'], str) or not data['certificate_id']:
        raise ValueError('invalid payload')
    if not isinstance(data['region'], str) or not data['region']:
        raise ValueError('invalid payload')
    if not isinstance(data['issued_at'], str) or not data['issued_at']:
        raise ValueError('invalid payload')
    amount = data['megawatt_hours']
    if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount <= 0:
        raise ValueError('invalid payload')
    return {field: data[field] for field in fields}

