import base64
import hashlib
import hmac
import os

def hash_contractor_pin(pin: str) -> str:
    if not pin:
        raise ValueError('PIN must not be empty')
    iterations = 100000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, iterations)
    encoded_salt = base64.urlsafe_b64encode(salt).decode('ascii')
    return f'{iterations}${encoded_salt}${digest.hex()}'

def verify_contractor_pin(pin: str, stored: str) -> bool:
    if not pin or not stored:
        return False
    try:
        iteration_text, encoded_salt, expected = stored.split('$', 2)
        iterations = int(iteration_text)
        salt = base64.urlsafe_b64decode(encoded_salt.encode('ascii'))
        if iterations < 100000 or len(salt) == 0:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, iterations)
        return hmac.compare_digest(actual.hex(), expected)
    except (ValueError, TypeError, UnicodeError):
        return False

