import hashlib
import hmac
import os

def hash_access_pin(pin: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_access_pin(pin: str, stored: str) -> bool:
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

def schedule_container_ports(pin: str, stored: str, requested: list[int], available: list[int]) -> list[int]:
    if not verify_access_pin(pin, stored):
        raise ValueError('invalid PIN')
    ports = sorted(set(requested))
    if any((port < 1 or port > 65535 for port in ports)):
        raise ValueError('invalid port')
    if not set(ports).issubset(set(available)):
        raise ValueError('unavailable port')
    return ports

