import os
import tempfile

def generate_benefits_report(records: list[dict[str, object]], income_limit: float) -> str:
    if income_limit < 0:
        raise ValueError('income_limit must not be negative')
    eligible = [record for record in records if int(record['household_size']) >= 2 and float(record['annual_income']) <= income_limit]
    eligible.sort(key=lambda record: str(record['name']))
