        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['name', 'household_size', 'annual_income'])
            for record in eligible:
                writer.writerow([record['name'], record['household_size'], f"{float(record['annual_income']):.2f}"])
        with open(path, newline='') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

