    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    suffix = ''.join((secrets.choice(alphabet) for _ in range(8)))
    return f'R{table_number:03d}{guest_count:02d}-{suffix}'

