import hashlib
import hmac
import json

def verify_harvest_webhook(payload: str, signature: str, secret: str) -> dict:
    if not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('vineyard'), str):
        raise ValueError('invalid payload')
    harvests = data.get('harvests')
    if not isinstance(harvests, list):
        raise ValueError('invalid payload')
    result = []
    for harvest in harvests:
        if not isinstance(harvest, dict):
            raise ValueError('invalid payload')
        block = harvest.get('block')
        tons = harvest.get('tons')
        if not isinstance(block, str) or not isinstance(tons, (int, float)) or isinstance(tons, bool):
            raise ValueError('invalid payload')
        result.append({'block': block, 'tons': tons})
    result.sort(key=lambda item: item['block'])
    return {'vineyard': data['vineyard'], 'harvests': result}

