class _MaintenanceHandler(xml.sax.handler.ContentHandler):

    def __init__(self) -> None:
        super().__init__()
        self.records = []
        self.current = None
        self.field = None
        self.text = []

    def startElement(self, name, attrs):
        if name == 'record':
            self.current = {}
        elif self.current is not None:
            self.field = name
            self.text = []

    def characters(self, content):
        if self.field is not None:
            self.text.append(content)

    def endElement(self, name):
        if name == 'record':
            self.records.append(self.current)
            self.current = None
        elif self.current is not None and self.field == name:
            self.current[name] = ''.join(self.text).strip()
            self.field = None
            self.text = []

def due_maintenance(xml_text: str) -> list[dict[str, object]]:
    handler = _MaintenanceHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    parser.parse(io.StringIO(xml_text))
    records = []
    for record in handler.records:
        if record.get('status', '') != 'due':
            continue
        records.append({'unit': record.get('unit', ''), 'hours': int(record.get('hours', '0')), 'task': record.get('task', '')})
    records.sort(key=lambda item: item['hours'], reverse=True)
    return records

