    def visit(node, record):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
            if node.id not in {'attended', 'total', 'late'}:
                raise ValueError('unknown name')
            return record[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.Not, ast.UAdd, ast.USub)):
            value = visit(node.operand, record)
            if isinstance(node.op, ast.Not):
                return not value
            return +value if isinstance(node.op, ast.UAdd) else -value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left, right = (visit(node.left, record), visit(node.right, record))
            operation = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)]
            return operation(left, right)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            values = [visit(item, record) for item in node.values]
            result = values[0]
            for value in values[1:]:
                result = result and value if isinstance(node.op, ast.And) else result or value
            return result
        if isinstance(node, ast.Compare):
            left = visit(node.left, record)
            operations = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            for op, comparator in zip(node.ops, node.comparators):
                if type(op) not in operations:
                    raise ValueError('unsupported comparison')
                right = visit(comparator, record)
                if not operations[type(op)](left, right):
                    return False
                left = right
            return True
        raise ValueError('unsupported expression')
    selected = []
    for record in records:
        try:
            result = visit(tree, record)
        except Exception as exc:
            raise ValueError('invalid rule') from exc
        if not isinstance(result, bool):
            raise ValueError('rule must return boolean')
        if result:
