def write_station_report(base_dir: str, relative_name: str, stations: list[tuple[str, int, int]]) -> str:
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, relative_name))
    try:
        inside = os.path.commonpath([base, path]) == base
    except ValueError:
