def create_donation_record(donor_id: str, amount_cents: int, pin: str) -> dict:
    if not isinstance(donor_id, str) or not donor_id:
        raise ValueError('invalid donor_id')
    if isinstance(amount_cents, bool) or not isinstance(amount_cents, int) or amount_cents <= 0:
        raise ValueError('invalid amount_cents')
