    if not isinstance(record, dict) or not isinstance(pin, str):
        return False
    value = record.get('pin_digest')
    if not isinstance(value, str) or ':' not in value:
        return False
    salt_text, expected = value.split(':', 1)
    try:
        salt = bytes.fromhex(salt_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000).hex()
    return hmac.compare_digest(actual, expected)

