def select_reservations(reservations: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    try:
        tree = ast.parse(rule, mode='eval')
    except SyntaxError as exc:
        raise ValueError('invalid rule') from exc
    names = {'guests', 'total', 'duration'}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in names:
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = evaluate(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = evaluate(child, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for operation, right_node in zip(node.ops, node.comparators):
                if type(operation) not in comparisons:
                    raise ValueError('invalid rule')
                right = evaluate(right_node, values)
                if not comparisons[type(operation)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max'}) and (not node.keywords):
            return min((evaluate(arg, values) for arg in node.args)) if node.func.id == 'min' else max((evaluate(arg, values) for arg in node.args))
        raise ValueError('invalid rule')
    selected = []
    for reservation in reservations:
        values = {name: reservation[name] for name in names}
        if evaluate(tree.body, values):
