import xml.etree.ElementTree as ET

def quotation_from_xml(xml: str) -> dict:
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'quotation':
        raise ValueError('missing quotation root')
    event = root.find('event')
    client = root.find('client')
    items_node = root.find('items')
    if event is None or client is None or items_node is None:
        raise ValueError('missing required element')
    items = []
    total = 0.0
    for node in items_node.findall('item'):
        name = node.find('name')
        quantity = node.find('quantity')
        price = node.find('unit_price')
        if name is None or quantity is None or price is None:
            raise ValueError('missing item element')
        try:
            count = int((quantity.text or '').strip())
            unit_price = float((price.text or '').strip())
        except ValueError as exc:
            raise ValueError('invalid item value') from exc
        if count <= 0 or unit_price < 0:
            raise ValueError('invalid item value')
        item = {'name': (name.text or '').strip(), 'quantity': count, 'unit_price': unit_price}
        items.append(item)
        total += count * unit_price
    return {'event': (event.text or '').strip(), 'client': (client.text or '').strip(), 'items': items, 'total': total}

