        self.root = None
        self.stack = []
        self.text = []
        self.event = None
        self.client = None
        self.items = []
        self.current = None

    def startElement(self, name, attrs):
        self.stack.append(name)
        self.text = []
        if name == 'quotation':
            self.root = name
        elif name == 'item':
            self.current = {}

    def characters(self, content):
        self.text.append(content)

    def endElement(self, name):
        value = ''.join(self.text).strip()
        if name == 'event':
            self.event = value
        elif name == 'client':
            self.client = value
        elif self.current is not None and name in ('name', 'quantity', 'unit_price'):
            self.current[name] = value
        elif name == 'item':
            if set(self.current) != {'name', 'quantity', 'unit_price'}:
                raise ValueError('missing item element')
            try:
                count = int(self.current['quantity'])
                price = float(self.current['unit_price'])
            except ValueError as exc:
                raise ValueError('invalid item value') from exc
            if count <= 0 or price < 0:
                raise ValueError('invalid item value')
            self.items.append({'name': self.current['name'], 'quantity': count, 'unit_price': price})
            self.current = None
        self.stack.pop()
        self.text = []

