import os

def create_credential(value: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', value.encode(), salt, 120000)
    return salt.hex() + '$' + digest.hex()

def verify_credential(value: str, stored: str) -> bool:
    try:
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', value.encode(), salt, 120000)
    return hmac.compare_digest(actual, expected)

