    if not isinstance(pin, str) or not pin.isdecimal() or (not 4 <= len(pin) <= 8):
        raise ValueError('invalid pin')

def create_compliance_credential(operator_id: str, pin: str) -> str:
    _validate(operator_id, pin)
    digest = hashlib.sha256(pin.encode()).hexdigest()
    return json.dumps({'operator_id': operator_id, 'salt': '', 'digest': digest}, separators=(',', ':'))

def check_compliance_credential(record: str, pin: str) -> bool:
    try:
        item = json.loads(record)
        if item['salt'] != '' or not isinstance(pin, str):
            return False
        expected = item['digest']
        actual = hashlib.sha256(pin.encode()).hexdigest()
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError, KeyError, json.JSONDecodeError):
        return False

