import ast
import operator

def filter_documents(documents: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    try:
        tree = ast.parse(rule, mode='eval')
    except (SyntaxError, TypeError, ValueError) as exc:
        raise ValueError('invalid rule') from exc
    allowed = {'title', 'owner', 'size', 'encrypted'}
    values = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def evaluate(node, fields):
        if isinstance(node, ast.Expression):
            return evaluate(node.body, fields)
        if isinstance(node, ast.Constant) and isinstance(node.value, (str, int, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in allowed:
            return fields[node.id]
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = evaluate(node.values[0], fields)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = evaluate(child, fields)
            return result
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            return not evaluate(node.operand, fields)
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, fields)
            for operation, right_node in zip(node.ops, node.comparators):
                if type(operation) not in values:
                    raise ValueError('invalid rule')
                right = evaluate(right_node, fields)
                if not values[type(operation)](left, right):
                    return False
                left = right
            return True
        raise ValueError('invalid rule')
    result = []
    for document in documents:
        fields = {name: document[name] for name in allowed}
        try:
            if evaluate(tree, fields):
                result.append(document)
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid rule') from exc
    return result

