import os
from pathlib import Path

def write_access_report(base_dir: str, relative_name: str, grants: list[tuple[str, str]]) -> str:
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        inside = os.path.commonpath((str(base), str(target))) == str(base)
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('invalid output path')
    target.parent.mkdir(parents=True, exist_ok=True)
    ordered = sorted(grants, key=lambda grant: (grant[1], grant[0]))
    with target.open('w', encoding='utf-8', newline='') as stream:
        stream.write('user,role\n')
        for user, role in ordered:
            stream.write(f'{user},{role}\n')
    return str(target)

