import hashlib
import hmac
import json

def collect_verified_evidence(body: str, signature: str, key: bytes) -> list[dict]:
    try:
        expected = hmac.new(key, body.encode('utf-8'), hashlib.sha256).hexdigest()
    except (AttributeError, TypeError, UnicodeError) as exc:
        raise ValueError('invalid input') from exc
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict) or not isinstance(data.get('records'), list):
        raise ValueError('invalid records')
    records = data['records']
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        for field in ('id', 'category', 'evidence'):
            if not isinstance(record.get(field), str) or not record[field]:
                raise ValueError('invalid record')
    return sorted(records, key=lambda record: record['id'])

