                if isinstance(node.op, ast.Or) and result:
                    return result
                result = evaluate(child, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for operation, child in zip(node.ops, node.comparators):
                right = evaluate(child, values)
                functions = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
