import hmac
import json
import os

def calculate_premium(policy: dict[str, object]) -> dict[str, object]:
    required = ('policy_id', 'property_type', 'property_value', 'deductible', 'claims')
    if any((field not in policy for field in required)):
        raise ValueError('policy is missing a required field')
    policy_id = policy['policy_id']
    property_type = policy['property_type']
    property_value = policy['property_value']
    deductible = policy['deductible']
    claims = policy['claims']
    if not isinstance(policy_id, str) or property_type not in {'house', 'apartment', 'condo'}:
        raise ValueError('invalid policy details')
    if not isinstance(property_value, int) or property_value <= 0:
        raise ValueError('property_value must be positive')
    if not isinstance(deductible, int) or deductible < 0:
        raise ValueError('deductible must be non-negative')
    if not isinstance(claims, int) or claims < 0:
        raise ValueError('claims must be non-negative')
    rates = {'house': 45, 'apartment': 38, 'condo': 41}
    premium = property_value * rates[property_type] // 10000
    if deductible >= 1000:
        premium = premium * 95 // 100
    premium = premium * (100 + 10 * claims) // 100
    key = os.environ.get('PROPERTY_SIGNING_KEY')
    if key is None:
        raise RuntimeError('PROPERTY_SIGNING_KEY is not set')
    payload = json.dumps({'policy_id': policy_id, 'annual_premium': premium}, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return {'policy_id': policy_id, 'annual_premium': premium, 'signature': signature}

