import ast
import operator

def _value(node, env):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in env:
            raise NameError(node.id)
        return env[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _value(node.operand, env)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        left, right = (_value(node.left, env), _value(node.right, env))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp):
        result = _value(node.values[0], env)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _value(child, env)
        return result
    if isinstance(node, ast.Compare):
        left = _value(node.left, env)
        checks = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
        for op, child in zip(node.ops, node.comparators):
            right = _value(child, env)
            if type(op) not in checks or not checks[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_value(x, env) for x in node.args])
    raise ValueError('invalid rule')

def schedule_pickups(records: list[dict], rule: str) -> list[str]:
    tree = ast.parse(rule, mode='eval')
    selected = [r for r in records if _value(tree.body, r)]
    selected.sort(key=lambda r: (r['day'], -r['weight'], r['id']))
    return [r['id'] for r in selected]

