import os
from numbers import Real

def build_purchase_order(order: dict[str, object]) -> dict[str, object]:
    token = os.environ.get('PROCUREMENT_API_TOKEN')
    if not token:
        raise RuntimeError('PROCUREMENT_API_TOKEN is required')
    vendor = order.get('vendor')
    currency = order.get('currency')
    raw_items = order.get('items')
    if not isinstance(vendor, str) or not vendor:
        raise ValueError('vendor must be a non-empty string')
    if not isinstance(currency, str) or not currency:
        raise ValueError('currency must be a non-empty string')
    if not isinstance(raw_items, list) or not raw_items:
        raise ValueError('items must be a non-empty list')
    items = []
    total = 0.0
    for raw in raw_items:
        if not isinstance(raw, dict):
            raise ValueError('each item must be a mapping')
        sku = raw.get('sku')
        quantity = raw.get('quantity')
        unit_price = raw.get('unit_price')
        if not isinstance(sku, str) or not sku:
            raise ValueError('sku must be a non-empty string')
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('quantity must be a positive integer')
        if isinstance(unit_price, bool) or not isinstance(unit_price, Real) or unit_price < 0:
            raise ValueError('unit_price must be a non-negative number')
        items.append({'sku': sku, 'quantity': quantity, 'unit_price': unit_price})
        total += quantity * unit_price
    items.sort(key=lambda item: item['sku'])
    return {'method': 'POST', 'path': '/purchase-orders', 'headers': {'Authorization': f'Bearer {token}', 'Content-Type': 'application/json'}, 'body': {'vendor': vendor, 'currency': currency, 'items': items, 'total': round(total, 2)}}

