import xml.etree.ElementTree as ET

def parse_lab_results(xml_text: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'lab_report' or 'patient_id' not in root.attrib:
        raise ValueError('invalid report')
    required = ('code', 'value', 'unit', 'status')
    results = []
    for element in root.findall('result'):
        if any((name not in element.attrib for name in required)):
            raise ValueError('incomplete result')
        results.append({name: element.attrib[name] for name in required})
    return sorted(results, key=lambda item: item['code'])

