import csv
from pathlib import Path

def load_shifts(base_dir: str, filename: str) -> list[tuple[str, str, int]]:
    base = Path(base_dir).resolve()
    path = (base / filename).resolve()
    try:
        path.relative_to(base)
    except ValueError:
        raise ValueError('file is outside base directory')
    with path.open('r', encoding='utf-8', newline='') as handle:
        rows = csv.DictReader(handle)
        shifts = [(row['worker'], row['date'], int(row['hours'])) for row in rows]
    return sorted(shifts, key=lambda shift: (shift[1], shift[0]))

