import os
import re
_ITERATIONS = 120000

def _make_verifier(pin: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, _ITERATIONS)
    return f'{_ITERATIONS}${salt.hex()}${digest.hex()}'

def _check_verifier(pin: str, verifier: str) -> bool:
    try:
        iterations_text, salt_text, digest_text = verifier.split('$', 2)
        iterations = int(iterations_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (AttributeError, ValueError):
        return False
    if iterations <= 0 or not salt or (not expected):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, iterations)
    return hmac.compare_digest(actual, expected)

def create_locale_entry(locale: str, text: str, editor_pin: str) -> dict:
    if not isinstance(locale, str) or re.fullmatch('[a-z]{2}', locale) is None:
        raise ValueError('invalid locale')
    if not isinstance(editor_pin, str) or re.fullmatch('[0-9]{4}', editor_pin) is None:
        raise ValueError('invalid PIN')
    return {'locale': locale, 'text': text, 'editor_verifier': _make_verifier(editor_pin)}

