        if complaint['status'] not in {'open', 'closed'}:
            raise ValueError('invalid status')
    rows = sorted((complaint for complaint in complaints if complaint['status'] == 'open'), key=lambda complaint: complaint['id'])
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.complaints-', suffix='.tmp')
