    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['id', 'category', 'description', 'status'])
            for complaint in rows:
                writer.writerow([complaint['id'], complaint['category'], complaint['description'], complaint['status']])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return len(rows)

