        date = element.get('date')
        summary_element = element.find('summary')
        if version is None or date is None or summary_element is None:
            raise ValueError('invalid revision')
        try:
            number = int(version)
        except ValueError as exc:
            raise ValueError('invalid revision version') from exc
        if number <= 0:
            raise ValueError('invalid revision version')
        revisions.append({'version': version, 'date': date, 'summary': ''.join(summary_element.itertext()), '_number': number})
    revisions.sort(key=lambda item: item['_number'], reverse=True)
    for revision in revisions:
        del revision['_number']
    return revisions

