import xml.sax.handler

class _RevisionHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.revisions = []
        self.current = None
        self.summary_parts = []
        self.in_summary = False

    def startElement(self, name, attrs):
        if name == 'revision':
            self.current = {'version': attrs.get('version'), 'date': attrs.get('date')}
            self.summary_parts = []
        elif name == 'summary' and self.current is not None:
            self.in_summary = True

    def characters(self, content):
        if self.in_summary:
            self.summary_parts.append(content)

    def endElement(self, name):
        if name == 'summary':
            self.in_summary = False
        elif name == 'revision':
            if self.current['version'] is None or self.current['date'] is None:
                raise ValueError('invalid revision')
            try:
                number = int(self.current['version'])
            except ValueError as exc:
                raise ValueError('invalid revision version') from exc
            if number <= 0 or not self.summary_parts:
                raise ValueError('invalid revision')
            self.current['summary'] = ''.join(self.summary_parts)
            self.current['_number'] = number
            self.revisions.append(self.current)
            self.current = None

def parse_plan_revisions(xml_text: str) -> list[dict[str, str]]:
    handler = _RevisionHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    try:
        xml.sax.parseString(xml_text, handler)
    except (xml.sax.SAXException, ValueError) as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid XML') from exc
    handler.revisions.sort(key=lambda item: item['_number'], reverse=True)
    for revision in handler.revisions:
        del revision['_number']
    return handler.revisions

