import os
_ITERATIONS = 100000

def create_bom_source(source_name: str, api_secret: str, component_ids: list[str]) -> dict[str, object]:
    source_name = source_name.strip()
    if not source_name or not api_secret:
        raise ValueError('source name and API secret are required')
    components = sorted({component.strip() for component in component_ids})
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, _ITERATIONS)
    return {'source_name': source_name, 'component_ids': components, 'secret_hash': salt.hex() + '$' + digest.hex()}

def verify_bom_source(record: dict[str, object], source_name: str, api_secret: str) -> bool:
    try:
        if record.get('source_name') != source_name:
            return False
        stored = record['secret_hash']
        salt_text, digest_text = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', api_secret.encode(), salt, _ITERATIONS)
        return hmac.compare_digest(actual, expected)
    except (AttributeError, KeyError, TypeError, ValueError):
        return False

