import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise NameError(node.id)
        return values[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _evaluate(node.operand, values)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        result = _evaluate(node.values[0], values)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                return result
            result = _evaluate(child, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        functions = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}
        for operation, child in zip(node.ops, node.comparators):
            if type(operation) not in functions:
                raise ValueError('invalid expression')
            right = _evaluate(child, values)
            if not functions[type(operation)](left, right):
                return False
            left = right
        return True
    raise ValueError('invalid expression')

def select_prescriptions(prescriptions: list[dict[str, object]], rule: str) -> list[str]:
    try:
        tree = ast.parse(rule, mode='eval')
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc
    selected = []
    for prescription in prescriptions:
        values = {name: prescription[name] for name in ('sphere', 'cylinder', 'axis', 'age')}
        if _evaluate(tree.body, values):
            selected.append(prescription)
    selected.sort(key=lambda item: -(abs(item['sphere']) + abs(item['cylinder'])))
    return [item['id'] for item in selected]

