def parse_bracket(xml: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml)
        matches = []
        for match in root.findall('match'):
            match_id = match.attrib['id']
            players = match.findall('player')
            if len(players) != 2:
                raise ValueError('each match must have two players')
            first_id = players[0].attrib['id']
            second_id = players[1].attrib['id']
            first_score = int(players[0].attrib['score'])
            second_score = int(players[1].attrib['score'])
            if first_score == second_score:
                raise ValueError('tied match')
            if first_score > second_score:
                winner, loser = (first_id, second_id)
            else:
                winner, loser = (second_id, first_id)
            matches.append({'match': match_id, 'winner': winner, 'loser': loser})
        return matches
    except (ET.ParseError, KeyError, ValueError, TypeError) as exc:
        if isinstance(exc, ValueError) and str(exc) in {'each match must have two players', 'tied match'}:
