import re

def verify_feature_flags(document: str, signing_key: str) -> dict[str, bool]:
    if '\n' not in document:
        raise ValueError('invalid document')
    header, payload = document.split('\n', 1)
    if not re.fullmatch('sig=[0-9a-f]{64}', header) or not payload:
        raise ValueError('invalid document')
    expected = hmac.new(signing_key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    supplied = header[4:]
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
