    for line in payload.split('\n'):
        match = re.fullmatch('([a-z][a-z0-9_]*)=(true|false)', line)
        if match is None:
            raise ValueError('invalid flag')
        name, value = match.groups()
        if name in flags:
            raise ValueError('duplicate flag')
        flags[name] = value == 'true'
    return flags

