def extract_reservations(xml_text: str) -> list[tuple[str, int]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('malformed XML') from exc
    result = []
    for reservation in root.iter('reservation'):
        guest_node = reservation.find('guest')
        party_node = reservation.find('party_size')
        status_node = reservation.find('status')
        if guest_node is None or party_node is None or status_node is None:
            raise ValueError('missing reservation field')
        guest = (guest_node.text or '').strip()
        if not guest:
            raise ValueError('empty guest name')
        try:
            party_size = int((party_node.text or '').strip())
        except ValueError as exc:
            raise ValueError('invalid party size') from exc
        if party_size <= 0:
            raise ValueError('invalid party size')
        if (status_node.text or '').strip() == 'confirmed':
            result.append((guest, party_size))
    return sorted(result, key=lambda item: item[0])

