class _ReservationHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        self.current = None
        self.field = None
        self.text = []
        self.result = []

    def startElement(self, name, attrs):
        if name == 'reservation':
            self.current = {}
        elif self.current is not None and name in ('guest', 'party_size', 'status'):
            self.field = name
            self.text = []

    def characters(self, content):
        if self.field is not None:
            self.text.append(content)

    def endElement(self, name):
        if self.current is not None and name in ('guest', 'party_size', 'status'):
            self.current[name] = ''.join(self.text).strip()
            self.field = None
            self.text = []
        elif name == 'reservation' and self.current is not None:
            if any((key not in self.current for key in ('guest', 'party_size', 'status'))):
                raise ValueError('missing reservation field')
            guest = self.current['guest']
            if not guest:
                raise ValueError('empty guest name')
            try:
                party_size = int(self.current['party_size'])
            except ValueError as exc:
                raise ValueError('invalid party size') from exc
            if party_size <= 0:
                raise ValueError('invalid party size')
            if self.current['status'] == 'confirmed':
                self.result.append((guest, party_size))
            self.current = None

def extract_reservations(xml_text: str) -> list[tuple[str, int]]:
    handler = _ReservationHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
