        raise ValueError('invalid seller')
    seller_id = seller.get('seller_id')
    display_name = seller.get('display_name')
    categories = seller.get('categories')
    if not isinstance(seller_id, str) or not seller_id or (not isinstance(display_name, str)):
        raise ValueError('invalid seller')
    if categories is not None and (not isinstance(categories, list) or not all((isinstance(x, str) for x in categories))):
        raise ValueError('invalid categories')
    result = {'seller_id': seller_id, 'display_name': display_name.strip()}
    if categories is not None:
        result['categories'] = sorted(set(categories))
    return result

