import hashlib
import hmac
import os

def _valid_pin(pin: str) -> bool:
    return isinstance(pin, str) and len(pin) == 6 and all(('0' <= c <= '9' for c in pin))

def hash_maintenance_pin(pin: str) -> str:
    if not _valid_pin(pin):
        raise ValueError('PIN must contain exactly six ASCII digits')
    salt = os.urandom(16)
