import hashlib
import hmac
import os

def create_points_receipt(account_id: str, entries: list[tuple[str, int]]) -> dict[str, object]:
    if not account_id:
        raise ValueError('account_id must not be empty')
    key = os.environ.get('LOYALTY_SIGNING_KEY')
    if key is None:
        raise RuntimeError('LOYALTY_SIGNING_KEY is not set')
    points = sum((value for owner, value in entries if owner == account_id and value > 0))
    payload = f'{account_id}:{points}'
    signature = hmac.new(key.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return {'account_id': account_id, 'points': points, 'payload': payload, 'signature': signature}

