import json
from pathlib import Path

def write_appraisal_record(base_dir: str, relative_name: str, item_name: str, estimated_value: float) -> str:
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('record path is outside base directory')
    if target.suffix.lower() != '.json':
        raise ValueError('record name must end in .json')
    target.parent.mkdir(parents=True, exist_ok=True)
    content = json.dumps({'item_name': item_name, 'estimated_value': estimated_value}, indent=2, sort_keys=True, ensure_ascii=False) + '\n'
    target.write_text(content, encoding='utf-8')
    return str(target)

