from pathlib import Path

def generate_badge_report(base_dir: str, relative_name: str, badge_ids: list[str]) -> str:
    if not relative_name:
        raise ValueError('relative_name must not be empty')
    if any((not badge_id for badge_id in badge_ids)):
        raise ValueError('badge IDs must not be empty')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('report path is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(''.join((f'{badge_id}\n' for badge_id in sorted(badge_ids))))
    return str(target)

