import xml.etree.ElementTree as ET

def calculate_commission(xml_text: str) -> float:
    try:
        root = ET.fromstring(xml_text)
        price_node = root.find('.//sale_price')
        rate_node = root.find('.//commission_rate')
        if price_node is None or rate_node is None:
            raise ValueError
        if price_node.text is None or rate_node.text is None:
            raise ValueError
        price = float(price_node.text.strip())
        rate = float(rate_node.text.strip())
    except (ET.ParseError, TypeError, ValueError):
        raise ValueError('invalid commission XML')
    return round(price * rate / 100, 2)

