import ast

def _evaluate(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError('unknown name')
        return names[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left = _evaluate(node.left, names)
        right = _evaluate(node.right, names)
        return {ast.Add: lambda: left + right, ast.Sub: lambda: left - right, ast.Mult: lambda: left * right, ast.Div: lambda: left / right}[type(node.op)]()
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _evaluate(node.operand, names)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        values = [_evaluate(item, names) for item in node.values]
        return all(values) if isinstance(node.op, ast.And) else any(values)
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, names)
        for operation, comparator in zip(node.ops, node.comparators):
            right = _evaluate(comparator, names)
            if not {ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right, ast.Eq: left == right, ast.NotEq: left != right}[type(operation)]:
                return False
            left = right
        return True
    raise ValueError('unsupported expression')

def calculate_premiums(properties: list[dict[str, float]], eligibility_rule: str) -> list[float]:
    try:
        tree = ast.parse(eligibility_rule, mode='eval').body
    except (SyntaxError, ValueError):
        raise ValueError('invalid rule')
    result = []
    for property_data in properties:
        names = {'value': property_data['value'], 'age': property_data['age'], 'claims': property_data['claims']}
        try:
            eligible = _evaluate(tree, names)
        except (KeyError, TypeError, ZeroDivisionError):
            raise ValueError('invalid rule')
        if eligible:
            result.append(round(property_data['value'] * 0.002 + property_data['claims'] * 125, 2))
    return result

