import hashlib
import hmac
import json

def verify_booking_event(body: str, signature: str, secret: str) -> dict:
    if not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    expected = hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body)
    except json.JSONDecodeError as exc:
        raise ValueError('invalid booking') from exc
    if not isinstance(data, dict):
        raise ValueError('invalid booking')
    if not isinstance(data.get('event'), str) or not isinstance(data.get('venue'), str):
        raise ValueError('invalid booking')
    if not isinstance(data.get('attendees'), list):
        raise ValueError('invalid booking')
    return {'event': data['event'], 'venue': data['venue'], 'attendees': sorted(data['attendees'])}

