import hashlib
import hmac
import json

def process_complaint_webhook(payload: str, digest: str, shared_key: str) -> list[dict[str, object]]:
    expected = hmac.new(shared_key.encode(), payload.encode(), hashlib.sha256).hexdigest().encode()
    if not hmac.compare_digest(expected, digest.encode()):
        raise ValueError('invalid digest')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('complaints'), list):
        raise ValueError('invalid complaints')
    complaints = data['complaints']
    for item in complaints:
        if not isinstance(item, dict) or not isinstance(item.get('id'), int) or isinstance(item.get('id'), bool) or (not isinstance(item.get('status'), str)):
            raise ValueError('invalid complaint')
    return sorted((item for item in complaints if item['status'] == 'open'), key=lambda item: item['id'])

