import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.Name) and node.id in values:
        return values[node.id]
    if isinstance(node, ast.BinOp):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        operations = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        for kind, function in operations.items():
            if isinstance(node.op, kind):
                return function(left, right)
    if isinstance(node, ast.UnaryOp):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.Not):
            return not value
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = True
            for item in node.values:
                result = _evaluate(item, values)
                if not result:
                    return result
            return result
        result = False
        for item in node.values:
            result = _evaluate(item, values)
            if result:
                return result
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        comparisons = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
        for operation, comparator in zip(node.ops, node.comparators):
            right = _evaluate(comparator, values)
            function = next((f for kind, f in comparisons.items() if isinstance(operation, kind)), None)
            if function is None or not function(left, right):
                return False
            left = right
        return True
    raise ValueError('invalid rule')

def select_crop_yields(records: list[dict], rule: str) -> list[dict]:
    try:
        tree = ast.parse(rule, mode='eval').body
        result = [record for record in records if _evaluate(tree, {'predicted_yield': record['predicted_yield'], 'moisture': record['moisture']})]
    except (SyntaxError, KeyError, TypeError, ValueError, ZeroDivisionError):
        raise ValueError('invalid rule')
    return sorted(result, key=lambda record: record['predicted_yield'], reverse=True)

