import os

def create_sample_record(sample_id: str, sequence: str, access_code: str) -> dict:
    normalized = sequence.upper()
    if not normalized or any((base not in 'ACGT' for base in normalized)):
        raise ValueError('invalid sequence')
    gc_percent = round((normalized.count('G') + normalized.count('C')) * 100 / len(normalized), 2)
