import base64
import hashlib
import hmac
import os

def store_audit_passphrase(passphrase: str) -> str:
    if not passphrase:
        raise ValueError('passphrase must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', passphrase.encode('utf-8'), salt, 100000)
    salt_text = base64.urlsafe_b64encode(salt).decode('ascii')
    digest_text = base64.urlsafe_b64encode(digest).decode('ascii')
    return 'audit$' + salt_text + '$' + digest_text

def check_audit_passphrase(passphrase: str, record: str) -> bool:
    if not passphrase or not isinstance(record, str):
        return False
    parts = record.split('$')
    if len(parts) != 3 or parts[0] != 'audit':
        return False
    try:
        salt = base64.urlsafe_b64decode(parts[1].encode('ascii'))
        expected = base64.urlsafe_b64decode(parts[2].encode('ascii'))
    except (ValueError, UnicodeEncodeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', passphrase.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

