import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Expression):
        return _evaluate(node.body, values)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values or not isinstance(values[node.id], (int, float)):
            raise NameError(node.id)
        return values[node.id]
    if isinstance(node, ast.UnaryOp):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
        if isinstance(node.op, ast.Not):
            return not value
    if isinstance(node, ast.BinOp):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = True
            for item in node.values:
                result = _evaluate(item, values)
                if not result:
                    return result
            return result
        result = False
        for item in node.values:
            result = _evaluate(item, values)
            if result:
                return result
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, item in zip(node.ops, node.comparators):
            right = _evaluate(item, values)
            funcs = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            if not funcs[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
        args = [_evaluate(arg, values) for arg in node.args]
        return min(args) if node.func.id == 'min' else max(args)
    raise SyntaxError('unsupported rule')

def filter_sessions(sessions: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    tree = ast.parse(rule, mode='eval')
    return [session for session in sessions if _evaluate(tree, session)]

