def create_attestation_token(policy_id: str, password: str) -> str:
    if not policy_id or ':' in policy_id:
        raise ValueError('invalid policy ID')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return f'{policy_id}:{salt.hex()}:{digest.hex()}'

def verify_attestation_token(token: str, policy_id: str, password: str) -> bool:
    try:
        token_policy, salt_text, digest_text = token.split(':')
        if token_policy != policy_id:
            return False
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (AttributeError, TypeError, ValueError):
        return False

