import xml.etree.ElementTree as ET

def parse_experiment_schedule(xml_text: str) -> list[tuple[str, str, int]]:
    try:
        root = ET.fromstring(xml_text)
        if root.tag != 'schedule':
            raise ValueError
        result = []
        for item in root:
            if item.tag != 'experiment':
                continue
            experiment_id = item.attrib['id']
            start = item.attrib['start']
            minutes = int(item.attrib['minutes'])
            result.append((experiment_id, start, minutes))
        return sorted(result, key=lambda entry: (entry[1], entry[0]))
    except (ET.ParseError, KeyError, TypeError, ValueError) as exc:
        raise ValueError('invalid schedule') from exc

