def list_subject_measurements(requester: dict, subject_id: str, records: list[dict]) -> list[dict]:
    if not subject_id:
        raise ValueError('subject_id must not be empty')
    matching = [record for record in records if record['subject_id'] == subject_id]
    if not matching:
        return []
    for record in matching:
        if record['tenant_id'] != requester['tenant_id']:
            raise PermissionError('access denied')
        if requester['role'] != 'coordinator' and record['owner_id'] != requester['id']:
            raise PermissionError('access denied')
    return sorted(matching, key=lambda record: record['visit_number'])

